/*
 * prog21_date_validator
 *
 * The original binary validates a single command‑line argument that must be a
 * date in the form YYYY‑MM‑DD.  If the argument is a syntactically correct date
 * (including correct handling of leap years) the program prints “VALID”.
 * For any other situation – missing argument, wrong length, wrong format,
 * out‑of‑range month or day – it prints “INVALID”.
 *
 * The implementation below follows the logic uncovered in the decompiled
 * state‑machine: length check, dash positions, digit checks, conversion to
 * integer values, month range test, leap‑year aware day‑range test and the
 * required output.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

static bool is_leap_year(int year)
{
    /* Leap year rule: (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) */
    if (year % 4 != 0) return false;
    if (year % 100 != 0) return true;
    return (year % 400 == 0);
}

int main(int argc, char *argv[])
{
    /* The original program accepts at least one argument (argc >= 2). */
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *s = argv[1];

    /* Length must be exactly 10 characters: YYYY-MM-DD */
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }

    /* Positions 4 and 7 must be dashes, all other positions must be digits. */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) {
            if (s[i] != '-') {
                puts("INVALID");
                return 0;
            }
        } else {
            if (!isdigit((unsigned char)s[i])) {
                puts("INVALID");
                return 0;
            }
        }
    }

    /* Convert the numeric fields.  The decompiled code performed the same
       arithmetic by subtracting the ASCII value of '0' from each digit. */
    int year  = (s[0] - '0') * 1000 +
                (s[1] - '0') * 100  +
                (s[2] - '0') * 10   +
                (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks for month and day. */
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }
    if (day < 1) {
        puts("INVALID");
        return 0;
    }

    /* Days per month for a non‑leap year. */
    static const int days_in_month[12] = {
        31, /* Jan */
        28, /* Feb */
        31, /* Mar */
        30, /* Apr */
        31, /* May */
        30, /* Jun */
        31, /* Jul */
        31, /* Aug */
        30, /* Sep */
        31, /* Oct */
        30, /* Nov */
        31  /* Dec */
    };

    int max_day = days_in_month[month - 1];

    /* Adjust February for leap years. */
    if (month == 2 && is_leap_year(year)) {
        max_day = 29;
    }

    if (day > max_day) {
        puts("INVALID");
        return 0;
    }

    /* All checks passed – the date is valid. */
    puts("VALID");
    return 0;
}
